 const applyCloudData=d=>{if(d.userId!==cloudUser.current)return;setProducts(d.products);setBrands(d.brands);setCustomers(d.customers);setSuppliers(d.suppliers);setTx(d.tx);setCloudReady(true);setCloudSyncError('');};
 useEffect(()=>{if(!homeGroup)return;const previous=document.activeElement,overflow=document.body.style.overflow;document.body.style.overflow='hidden';groupDialog.current?.querySelector('button')?.focus();const key=e=>{if(e.key==='Escape')setHomeGroup(null);if(e.key==='Tab'){const nodes=[...groupDialog.current.querySelectorAll('button,a')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener('keydown',key);return()=>{document.body.style.overflow=overflow;document.removeEventListener('keydown',key);previous?.focus?.();};},[homeGroup]);
 useEffect(()=>{const params=new URLSearchParams(window.location.search);if(params.get('section')==='installations'){setPage('installations');setNotificationJob(params.get('job')||'');}if(params.get('section')==='cashTransfers'){setPage('cashTransfers');setSelectedTransfer(params.get('transfer')||'');}let authTimer=setTimeout(()=>setAuthReady(true),3500);const applySession=async(session)=>{const u=session?.user||null;const changedUser=cloudUser.current!==(u?.id||null);cloudUser.current=u?.id||null;if(changedUser){setPhoneEditor(false);setProfile(null);setCloudReady(false);setTx([]);setProducts([]);setBrands([]);setCustomers([]);setSuppliers([]);setStaff([]);setInvoiceItems([]);setSearch('');setPartyLaunch(null);setSelectedSupplier('');setSelectedWarehouse('');setSelectedStockTransfer('');setSelectedTransfer('');setNotificationJob('');setHomeGroup(null);setPage('home');}setAuthUser(u);if(u){try{const {data:p,error}=await supabase.from('profiles').select('*').eq('id',u.id).maybeSingle();if(cloudUser.current!==u.id)return;if(error)console.error('profile',error);setProfile(p||{id:u.id,active:false,is_admin:false,permissions:{}});const requested=params.get('section');if(requested&&[...sections.map(x=>x[2]),'tahseel','warranty','cashTransfers','customerDebts','supplierBalances','exchangeRate','salesHistory','stockMovement','warehouse'].includes(requested)&&canOpenPage(p,requested))setPage(requested);if(params.get('section')==='warehouse'){setSelectedWarehouse(params.get('job')||'');setSelectedStockTransfer(params.get('stockTransfer')||'');setPage(params.get('stockTransfer')&&!p.is_admin&&p.user_type!=='warehouse'?(canOpenPage(p,'stock')?'stock':'home'):canOpenPage(p,'warehouse')?'warehouse':'salesHistory');}if(p?.active&&!['installer','warehouse'].includes(p.user_type)){const q=await supabase.rpc('solar_staff_directory');if(cloudUser.current===u.id)setStaff(q.data||[])}else setStaff([])}catch(e){console.error(e);if(cloudUser.current!==u.id)return;setProfile({id:u.id,active:false,is_admin:false,permissions:{}})}}else setProfile(null);setAuthReady(true);clearTimeout(authTimer)};supabase.auth.getSession().then(({data})=>applySession(data.session)).catch(e=>{console.error(e);setAuthReady(true)});const {data:listener}=supabase.auth.onAuthStateChange((_e,session)=>{setTimeout(()=>{applySession(session);if(session)loadCloud().then(d=>{applyCloudData(d)}).catch(console.error)},0)});const h=e=>{e.preventDefault();setInstallPrompt(e)};window.addEventListener('beforeinstallprompt',h);const installRequested=new URLSearchParams(window.location.search).get('install')==='1';const standalone=window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true;setIsStandalone(standalone);if(installRequested&&!standalone)setSharedInstall(true);setSessionUser(localStorage.getItem('solar_access_version')==='1'?'authorized':null);let live=true;const sync=async(fresh=false)=>{try{const {data:sessionData}=await supabase.auth.getSession();if(!sessionData.session)return;const d=await loadCloud({fresh});if(!live)return;applyCloudData(d)}catch(e){console.error(e);alert('تعذر تحميل البيانات المركزية. تحقق من الإنترنت')}};sync();const channel=supabase.channel('solar-v4-live').on('postgres_changes',{event:'*',schema:'public'},()=>sync(true)).subscribe();return()=>{live=false;window.removeEventListener('beforeinstallprompt',h);supabase.removeChannel(channel);listener.subscription.unsubscribe();clearTimeout(authTimer)}},[]);
 const save=async(k,v,set)=>{const actorId=cloudUser.current;const previous={solar_products:products,solar_brands:brands,solar_customers:customers,solar_suppliers:suppliers,solar_tx:tx}[k];try{const receipts=await saveCloud(k,v,previous);if(!actorId||cloudUser.current!==actorId)return false;set(k==='solar_tx'?v.map(t=>({...t,...receipts.find(r=>r.id===t.id)})):v);return receipts}catch(e){if(cloudUser.current!==actorId)return false;console.error(e);alert('لم يكتمل الحفظ. أعد تحميل البيانات وتحقق قبل إعادة المحاولة.');return false}};
