 const logout=async()=>{cloudUser.current=null;await disablePush().catch(()=>{});await supabase.auth.signOut();setAuthUser(null);setProfile(null);setCloudReady(false);setTx([]);setProducts([]);setCustomers([]);setSuppliers([]);setStaff([]);setPage('home');setHomeGroup(null)};
