function Master({onSubmit,rows}){return <><form onSubmit={onSubmit} className="card form"><input name="name" placeholder="الاسم" required/><input name="phone" placeholder="رقم الهاتف"/><button>حفظ</button></form><List rows={rows.map(x=>[x.name,x.phone])}/></>}
function TxForm({kind,products,parties,onSubmit}){return <form onSubmit={onSubmit} className="card form"><PartySearch rows={parties} name="party"/><select name="product" required><option value="">اختر المادة</option>{products.map(x=><option value={x.id} key={x.id}>{x.name} — متوفر {x.qty}</option>)}</select><input name="qty" type="number" step=".01" min=".01" placeholder="الكمية" required/><input name="price" type="number" step=".01" placeholder="السعر" required/><select name="currency"><option>USD</option><option>IQD</option></select><select name="mode"><option value="cash">نقدي</option><option value="credit">آجل</option></select><button>حفظ العملية</button></form>}
function List({rows}){return <div className="list">{rows.length?rows.map((r,i)=><div className="row" key={i}><b>{r[0]}</b><span>{r[1]}</span></div>):<div className="empty">لا توجد بيانات بعد</div>}</div>}

function InvoiceBuilder(props){
 const statuses=useWarehouseStatuses(props.kind==='sale'?props.history:[],props.onChanged),history=props.history.map(t=>({...t,warehouseStatus:statuses[t.id]||t.warehouseStatus}));
 return <CurrencyInvoice {...props} a4={a4} openA4={openA4} saveA4={saveA4} shareA4={shareA4} renderHistory={begin=><details className="deskHistory"><summary>الفواتير السابقة <span>{props.history.length}</span></summary><InvoiceHistory onWarrantyChanged={props.onChanged} onBeginEdit={begin} canDelete={props.kind==='purchase'||props.canDeleteSales} kind={props.kind} history={history} products={props.products} parties={props.parties} onDelete={props.onDeleteInvoice} onUpdate={props.onUpdateInvoice}/></details>}/>;
}

function SavedInvoiceExport({html,name}){const [open,setOpen]=useState(false);return <div className="savedInvoiceExport"><button type="button" aria-expanded={open} onClick={()=>setOpen(v=>!v)}>{open?'إخفاء خيارات التصدير':'معاينة وحفظ ومشاركة'}</button>{open&&<ReportActions enabled html={html} filename={name}/>}</div>;}
function InvoiceHistory({onWarrantyChanged,onBeginEdit,initialEdit=false,canDelete=false,kind,history,products,parties,onDelete,onUpdate}){
 const [editing,setEditing]=useState(initialEdit?history[0]?.id:null),[draft,setDraft]=useState(initialEdit?{...history[0],items:(history[0]?.items||[]).map(x=>({...x}))}:null),[query,setQuery]=useState(''),[saving,setSaving]=useState(false);
 const filtered=history.filter(t=>matchesReceipt(t,query));
 const begin=t=>{if(onBeginEdit){onBeginEdit(t);return;}setEditing(t.id);setDraft({...t,items:(t.items||[]).map(x=>({...x})),expenses:t.expenses||'',notes:t.notes||''})};
 const changeItem=(id,k,v)=>setDraft({...draft,items:draft.items.map(x=>x.id===id?{...x,[k]:v===''?'':+v}:x)});
 const saveEdit=async()=>{if(saving)return;setSaving(true);try{const subtotal=draft.items.reduce((a,x)=>a+(+x.qty||0)*(+x.price||0),0);if(await onUpdate(history.find(x=>x.id===editing),{...draft,subtotal,total:subtotal+(+draft.expenses||0)})){setEditing(null);setDraft(null)}}finally{setSaving(false)}};
 const savedDoc=(t,priced=true)=>{const d=kind==='purchase'?supplierDocument(t):salesDocument({...t,party_name:t.party,created_at:t.date,items:(t.items||[]).map(i=>({...i,product_name:i.name,brand_name:i.brand}))},priced);return a4(d.title,d.body,d.total,d.subtitle)};

 return <div className="history"><h3>الفواتير السابقة</h3><input className="receiptSearch" value={query} onChange={e=>setQuery(e.target.value)} placeholder="ابحث برقم الوصل أو الاسم…" aria-label="بحث الفواتير السابقة"/>{filtered.length===0?<div className="empty">لا توجد فواتير محفوظة</div>:filtered.slice().reverse().map((t,i)=><div className="historyItem" key={t.id}>{editing===t.id?<div className="editInvoice"><b>تعديل فاتورة {kind==='sale'?'بيع':'شراء'} #{receiptNumber(t)}</b><PartySearch rows={parties} value={draft.party||''} onChange={party=>setDraft({...draft,party})}/>{draft.items.map(x=><div className="editInvoiceLine" key={x.id}><b>{x.name}</b><label>العدد<input inputMode="decimal" value={x.qty} onChange={e=>changeItem(x.id,"qty",e.target.value.replace(/,/g,""))}/></label><label>السعر<input inputMode="numeric" value={x.price===""?"":fmt(x.price)} onChange={e=>changeItem(x.id,"price",e.target.value.replace(/,/g,""))}/></label><button className="dangerMini" onClick={()=>setDraft({...draft,items:draft.items.filter(y=>y.id!==x.id)})}>حذف المادة</button></div>)}<select value="" onChange={e=>{const p=products.find(x=>String(x.id)===e.target.value);if(p&&!draft.items.some(x=>x.id===p.id))setDraft({...draft,items:[...draft.items,{...p,qty:1,price:kind==='purchase'?p.cost:p.saleIqd}]})}}><option value="">+ إضافة مادة</option>{products.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><input inputMode="numeric" placeholder="المصاريف الإضافية" value={moneyValue(draft.expenses)} onChange={e=>setDraft({...draft,expenses:rawMoney(e.target.value)})}/><textarea placeholder="ملاحظات" value={draft.notes||''} onChange={e=>setDraft({...draft,notes:e.target.value})}/><div className="editActions"><button disabled={saving} onClick={saveEdit}>{saving?'جاري الحفظ…':'حفظ التعديل'}</button><button className="secondary" disabled={saving} onClick={()=>{setEditing(null);setDraft(null)}}>إلغاء</button></div></div>:<><details><summary className="deskSavedSummary"><span className="deskSavedIdentity">{kind==='sale'&&<WarehouseBadge status={t.warehouseStatus} compact/>}<b>{kind==='purchase'?'فاتورة شراء رقم':'فاتورة بيع رقم'} <bdi>{receiptNumber(t)}</bdi></b><span>{kind==='purchase'?'المجهّز: ':'العميل: '}{t.party||(kind==='purchase'?'غير محدد':'نقدي')}</span></span><time>{new Date(t.date).toLocaleDateString('ar-IQ')}</time><strong>{formatMoney(purchaseDisplayTotal(t).value,purchaseDisplayTotal(t).currency)} {currencyUnit(purchaseDisplayTotal(t).currency)}{t.sourceCurrency==='USD'&&<small className="historyMeta">كلفة المخزون: {fmt(t.total)} د.ع</small>}</strong></summary><div className="historyBody"><div>{t.party||'نقدي'}</div>{(t.items||[]).map((x,k)=><div className="historyLine" key={k}><span>{x.name}<small className="historyMeta">{x.brand||""}{x.brand&&x.category?" • ":""}{x.category||""}</small></span><span>{fmt(x.qty)} × {formatMoney(kind==='purchase'?x.sourcePrice??x.price:x.price,t.sourceCurrency)}</span><b>{formatMoney((+x.qty||0)*Number(kind==='purchase'?x.sourcePrice??x.price:x.price),t.sourceCurrency)} {currencyUnit(t.sourceCurrency)}</b></div>)}</div></details><div className="savedInvoiceActions">{kind==='sale'&&<WarrantyManage invoiceId={t.id} onChanged={onWarrantyChanged}/>}<SavedInvoiceExport html={savedDoc(t,true)} name={'وصل-'+receiptNumber(t)}/>{kind==="sale"&&<button onClick={()=>openA4(savedDoc(t,false))}>نسخة مخزنية</button>}<button onClick={()=>begin(t)}>تعديل</button>{canDelete&&<button className="dangerMini" onClick={()=>onDelete(t)}>حذف</button>}</div></>}</div>)}</div>
}
function InstallFirst({installPrompt,onInstalled}){
 const [msg,setMsg]=useState('');const [ios,setIos]=useState(false);const [android,setAndroid]=useState(false);
 useEffect(()=>{const ua=navigator.userAgent||'';setIos(/iPhone|iPad|iPod/i.test(ua));setAndroid(/Android/i.test(ua))},[]);
 const install=async()=>{if(installPrompt){await installPrompt.prompt();const choice=await installPrompt.userChoice;if(choice?.outcome==='accepted'){onInstalled();return}setMsg('لم يكتمل التثبيت. افتح الرابط في Chrome ثم اختر تثبيت التطبيق.');return}if(ios)setMsg('في Safari اضغط مشاركة □↑ ثم «إضافة إلى الشاشة الرئيسية» ثم «إضافة».');else if(android)setMsg('افتح هذا الرابط في Google Chrome، ثم اضغط ⋮ واختر «تثبيت التطبيق» أو «إضافة إلى الشاشة الرئيسية». لا تثبت أي APK يظهر من مصدر خارجي.');else setMsg('من قائمة المتصفح اختر تثبيت التطبيق / إضافة إلى الشاشة الرئيسية.')};
 return <main className="installFirstPage"><div className="installFirstCard"><div className="installInviteIcon">☀</div><h1>عبدالرحمن سولار</h1><p className="installLead">تثبيت آمن من المتصفح</p><button className="installMainBtn" onClick={install}>📱 تثبيت البرنامج</button>{android&&<div className="safeInstallNote"><b>Android</b><span>يتم التثبيت كتطبيق ويب PWA من Chrome فقط — بدون APK.</span></div>}{ios&&<div className="iosHint"><b>iPhone / iPad</b><span>Safari ← مشاركة □↑ ← إضافة إلى الشاشة الرئيسية</span></div>}{msg&&<div className="installHelp">{msg}</div>}<small>بعد التثبيت افتح التطبيق من الأيقونة ثم سجل الدخول.</small></div></main>
}
function AuthLogin({onLogin}){const [login,setLogin]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);const submit=async e=>{e.preventDefault();if(busy)return;setBusy(true);try{const x=await onLogin(login.trim(),password);setError(x||'')}finally{setBusy(false)}};return <main className="loginPage"><div className="loginCard"><div className="loginLogo"><MenuSymbol name="sun" size={35}/></div><h1>عبدالرحمن سولار V3.53.0</h1><p>تسجيل الدخول بالاسم أو البريد الإلكتروني</p><form onSubmit={submit}><input value={login} onChange={e=>setLogin(e.target.value)} autoComplete="username" aria-label="اسم المستخدم أو البريد الإلكتروني" placeholder="اسم المستخدم أو البريد الإلكتروني" required/><input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password" aria-label="الباسورد" placeholder="الباسورد" required/>{error&&<div className="loginError">{error}</div>}<button disabled={busy}>{busy?"جاري الدخول…":"دخول"}</button></form></div></main>}
