function BrandsManager({brands,setBrands}){const [edit,setEdit]=useState(null);const add=e=>{e.preventDefault();const f=new FormData(e.currentTarget),name=String(f.get('name')||'').trim();if(!name)return;if(brands.some(b=>b.name.toLowerCase()===name.toLowerCase()))return alert('البراند موجود مسبقاً');setBrands([...brands,{id:Date.now(),name}]);e.currentTarget.reset()};const saveEdit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),name=String(f.get('name')||'').trim();if(!name)return;setBrands(brands.map(b=>b.id===edit.id?{...b,name}:b));setEdit(null)};return <><form onSubmit={add} className="card form"><input name="name" placeholder="اسم البراند" required/><button>إضافة البراند</button></form>{edit&&<form onSubmit={saveEdit} className="card form"><b>تعديل البراند</b><input name="name" defaultValue={edit.name} required/><button>حفظ التعديل</button></form>}<div className="list">{brands.length===0?<div className="empty">لا توجد براندات بعد</div>:brands.map(b=><div className="row manageRow" key={b.id}><b>{b.name}</b><div className="rowActions"><button onClick={()=>setEdit(b)}>تعديل</button><button className="dangerMini" onClick={()=>confirm('حذف البراند من القائمة؟')&&setBrands(brands.filter(x=>x.id!==b.id))}>حذف</button></div></div>)}</div></>}

function PartyManager({canPay=false,customer=false,isAdmin=false,staff=[],rows,setRows,tx,onAdd,onPayment}){
 const [open,setOpen]=useState(null);
 const [edit,setEdit]=useState(null),[adding,setAdding]=useState(false),[formKey,setFormKey]=useState(0);
 const relevant=(r)=>tx.filter(t=>(t.partyId!=null?String(t.partyId)===String(r.id):t.party===r.name)&&(customer?['sale','system','customer_payment','system_payment'].includes(t.kind):['purchase','supplier_payment'].includes(t.kind)));
 const isPay=(t)=>['customer_payment','supplier_payment','system_payment'].includes(t.kind);
 const movementName=t=>customer?accountLabel(t):isPay(t)&&Number(t.total)<0?({charge_extra_expense:'مصروف إضافي',charge_old_balance:'حساب قديم',charge_other:'إضافة أخرى'}[t.mode]||'إضافة على الحساب'):isPay(t)?'تسديد':'فاتورة';
 const balance=(r)=>customer?relevant(r).reduce((sum,t)=>sum+accountEffect(t),0):tx.filter(t=>t.fxAccountEntry&&String(t.partyId)===String(r.id)&&t.accountRevision===(r.currencyRevision||0)).reduce((sum,t)=>sum+t.accountAmount,0);
 function editSave(e){e.preventDefault();const f=new FormData(e.currentTarget);const next=rows.map(r=>{if(r.id!==edit.id)return r;const owner=f.get('ownerId');return {...r,name:f.get('name'),phone:f.get('phone')||'',customerType:f.get('customerType')||'',ownerId:isAdmin&&owner?owner:r.ownerId};});setRows(next);setEdit(null)}
 return <div>
  <form key={formKey} onSubmit={async e=>{e.preventDefault();if(adding)return;setAdding(true);try{const ok=await onAdd(e);if(ok!==false)setFormKey(k=>k+1)}finally{setAdding(false)}}} className="card form">
   <input name="name" placeholder={customer?'اسم الزبون':'اسم المورد'} required/>
   <input name="phone" placeholder="رقم الهاتف"/>
   {customer?<select name="customerType" defaultValue=""><option value="">نوع الزبون</option><option value="مفرد - منظومات">مفرد - منظومات</option><option value="جملة - بيع جملة">جملة - بيع جملة</option></select>:null}
   {customer&&isAdmin?<select name="ownerId" defaultValue=""><option value="">اختر المستخدم المسؤول عن الزبون</option>{staff.map(u=><option key={u.id} value={u.id}>{u.display_name||u.username||'مستخدم'}</option>)}</select>:null}
   {customer&&<OpeningBalanceFields/>}<button disabled={adding}>{adding?'جاري الحفظ…':customer?'إضافة عميل':'إضافة مورد'}</button>
  </form>
  {edit?<form onSubmit={editSave} className="card form">
   <input name="name" defaultValue={edit.name}/>
   <input name="phone" defaultValue={edit.phone}/>
   {customer?<select name="customerType" defaultValue={edit.customerType||''}><option value="">نوع الزبون</option><option value="مفرد - منظومات">مفرد - منظومات</option><option value="جملة - بيع جملة">جملة - بيع جملة</option></select>:null}
   {customer&&isAdmin?<select name="ownerId" defaultValue={edit.ownerId||''}><option value="">اختر المستخدم المسؤول</option>{staff.map(u=><option key={u.id} value={u.id}>{u.display_name||u.username||'مستخدم'}</option>)}</select>:null}
   <button>حفظ التعديل</button>
  </form>:null}
  <div className="list">{rows.map(r=><div className="partyCard" key={r.id}>
   <div className="partyTop"><div><b>{r.name}</b><span>{customer?(r.customerType||''):('عملة الحساب: '+(r.accountCurrency||'IQD'))}</span></div><strong>الرصيد: {balance(r).toLocaleString('en-US',{maximumFractionDigits:2})} {customer?'د.ع':currencyLabel(r.accountCurrency)}</strong></div>
   <div className="partyActions"><button onClick={()=>setOpen(open===r.id?null:r.id)}>الحساب والفواتير</button>{!customer&&canPay?<button onClick={()=>onPayment(r)}>تسديد</button>:null}<button onClick={()=>setEdit(r)}>تعديل</button><button className="dangerMini" onClick={()=>confirm('حذف من القائمة؟ الحركات القديمة تبقى محفوظة.')&&setRows(rows.filter(x=>x.id!==r.id))}>حذف</button></div>
   {open===r.id?<div className="accountBox">{relevant(r).slice().reverse().map(t=><div className="accountLine" key={t.id}><span>{new Date(t.date).toLocaleDateString('ar-IQ')}</span><span>{movementName(t)}</span><b>{Number(t.total)<0?'+ ':isPay(t)?'− ':''}{fmt(Math.abs(t.total))} د.ع</b></div>)}</div>:null}
  </div>)}</div>
 </div>
}


function SystemSale({contact,products:catalogProducts,customers,installers=[],onSave,initialParty=''}){
 const [saving,setSaving]=useState(false),[warranty,setWarranty]=useState(blankWarranty),[saved,setSaved]=useState(null);
 const [items,setItems]=useState([]),[q,setQ]=useState(''),[party,setParty]=useState(initialParty),[salePrice,setSalePrice]=useState(''),[notes,setNotes]=useState(''),[installerId,setInstallerId]=useState(''),[scheduleEnabled,setScheduleEnabled]=useState(false),[installDate,setInstallDate]=useState(''),[installTime,setInstallTime]=useState(''),[address,setAddress]=useState('');
 const catalogVersion=useMemo(()=>JSON.stringify(catalogProducts||[]),[catalogProducts]);
 const inventory=useWarehouseInventory({versionKey:catalogVersion}),products=inventory.products;
 const expenses=0;
 const cost=items.reduce((a,i)=>a+(+i.qty||0)*(+i.cost||0),0),profit=(+salePrice||0)-cost-(+expenses||0);
 const add=p=>{if(!items.some(i=>i.id===p.id))setItems([...items,{...p,availableQty:+p.qty||0,qty:''}])};
 const installer=installers.find(u=>String(u.id)===String(installerId));
 const doc=(customerCopy=true)=>{
  const d=salesDocument({creatorName:contact?.display_name||contact?.username,creatorPhone:contact?.phone,warehouseId:Number(inventory.warehouseId),warehouseName:inventory.warehouseName,warranty:warrantyPolicy(warranty,items),draft:true,kind:'system',receipt_no:'مسودة',party_name:party,created_at:new Date().toISOString(),installerName:installer?.display_name||installer?.username,installation_status:'pending',customer_address:address,customer_phone:customers.find(c=>c.name===party)?.phone,install_date:scheduleEnabled?installDate:'',install_time:scheduleEnabled?installTime:'',notes,total:Number(salePrice||0),items:items.map(i=>({...i,product_name:i.name,brand_name:i.brand}))},customerCopy);
  return a4(d.title,d.body,d.total,d.subtitle);
 };
 const share=async(customerCopy)=>shareA4(customerCopy?'وصل-منظومة-للعميل':'وصل-منظومة-مخزني',(customerCopy?'وصل العميل':'وصل مخزني')+' - '+(party||'')+'\n'+items.map(i=>i.name+' × '+i.qty).join('\n')+(customerCopy?'\nالسعر: '+fmt(salePrice)+' د.ع':'\nكلفة المواد: '+fmt(cost)+' د.ع'),doc(customerCopy));
 const saveSystem=async()=>{if(saving)return;if(!inventory.ready||!inventory.warehouseId)return alert(inventory.error||'اختر المخزن وانتظر تحميل الرصيد');if(!party)return alert('اختر العميل');if(!installerId)return alert('اختيار مهندس التنصيب إجباري');if(!address.trim())return alert('اكتب عنوان التنصيب');if(scheduleEnabled&&(!installDate||!installTime))return alert('حدد يوم وساعة الموعد أو ألغِ خيار تحديد الموعد');const validation=invoiceError(items.map(i=>({...i,price:0})),products,'system');if(validation)return alert(validation);const guaranteeError=warrantyError(warranty,items);if(guaranteeError)return alert(guaranteeError);if(!Number.isFinite(Number(salePrice))||Number(salePrice)<=0||!Number.isFinite(Number(expenses||0))||Number(expenses||0)<0)return alert('أدخل سعر البيع والمصاريف بصورة صحيحة');setSaving(true);try{const ok=await onSave({warehouseId:Number(inventory.warehouseId),warehouseName:inventory.warehouseName,warranty:warrantyPolicy(warranty,items),items:items.map(i=>({...i,qty:+i.qty||0})),total:+salePrice,expenses:+expenses||0,cost,profit,currency:'IQD',party,notes,cash:true,installerId,installDate:scheduleEnabled?installDate:'',installTime:scheduleEnabled?installTime:'',customerAddress:address,customerPhone:customers.find(c=>c.name===party)?.phone||'',installationStatus:'pending'});if(!ok)return;inventory.refresh();if(ok.receiptNo){const d=salesDocument({kind:'system',...ok,installerName:installer?.display_name||installer?.username,installation_status:'pending',customer_address:address,customer_phone:customers.find(c=>c.name===party)?.phone,install_date:scheduleEnabled?installDate:'',install_time:scheduleEnabled?installTime:'',notes,warranty:ok.warranty||warrantyPolicy(warranty,items),party_name:party,created_at:ok.date||new Date().toISOString(),total:Number(salePrice),items:items.map(i=>({...i,product_name:i.name,brand_name:i.brand}))});setSaved({number:ok.receiptNo,token:ok.warrantyToken,html:a4(d.title,d.body,d.total,d.subtitle)});}setWarranty(blankWarranty());setItems([]);setParty('');setInstallerId('');setScheduleEnabled(false);setInstallDate('');setInstallTime('');setAddress('');setSalePrice('');setNotes('');alert('تم حفظ المنظومة وإسناد مهمة التنصيب للمهندس')}finally{setSaving(false)}};
 return <><InvoiceShell title="فاتورة بيع منظومة" saving={saving} className="systemWorkspace"><WarehouseField inventory={inventory} disabled={saving} label="مخزن تجهيز المنظومة"/>
  <section className="systemCustomerSection"><div className="systemStepTitle"><span>1</span><h2>العميل والفاتورة</h2></div><div className="deskMeta"><InvoiceField label="العميل · مطلوب"><PartySearch rows={customers} value={party} onChange={setParty}/></InvoiceField><InvoiceField label="نوع الفاتورة"><div className="deskReadonly">بيع منظومة مع تنصيب</div></InvoiceField><InvoiceField label="العملة"><div className="deskReadonly">الدينار العراقي (IQD)</div></InvoiceField></div></section>
  <section className="deskInstall"><div className="systemStepTitle"><span>2</span><h2>بيانات التنصيب</h2><small>المهندس والعنوان</small></div><div className="deskInstallGrid"><InvoiceField label="مهندس التنصيب · مطلوب"><select aria-label="مهندس التنصيب" required value={installerId} onChange={e=>setInstallerId(e.target.value)}><option value="">اختر مهندس التنصيب</option>{installers.map(u=><option key={u.id} value={u.id}>{u.display_name||u.username}</option>)}</select>{!installers.length&&<small>لا يوجد مهندس فعّال. أضف مستخدماً بنوع مهندس تنصيب أولاً.</small>}</InvoiceField><InvoiceField label="عنوان التنصيب · مطلوب"><input aria-label="عنوان التنصيب" value={address} onChange={e=>setAddress(e.target.value)} placeholder="المنطقة، الشارع، أقرب نقطة دالة…"/></InvoiceField></div>
  <label className="deskSchedule"><input type="checkbox" checked={scheduleEnabled} onChange={e=>{setScheduleEnabled(e.target.checked);if(!e.target.checked){setInstallDate('');setInstallTime('')}}}/>تحديد موعد التنصيب <small>اختياري — يمكن تحديده لاحقاً</small></label>
  {scheduleEnabled&&<div className="deskDates"><InvoiceField label="يوم التنصيب"><input aria-label="يوم التنصيب" required type="date" value={installDate} onChange={e=>setInstallDate(e.target.value)}/></InvoiceField><InvoiceField label="ساعة التنصيب"><input aria-label="ساعة التنصيب" required type="time" value={installTime} onChange={e=>setInstallTime(e.target.value)}/></InvoiceField></div>}</section>
  <div className="deskBody"><InvoiceCatalog availableOnly products={products} items={items} query={q} onQuery={setQ} onAdd={add}/><InvoiceItems products={products} items={items} kind="system" onEdit={(id,k,value)=>setItems(items.map(i=>i.id===id?{...i,[k]:value}:i))} onRemove={id=>setItems(items.filter(i=>i.id!==id))}/></div>
  <section className="systemPricingSection"><div className="systemStepTitle"><span>3</span><h2>سعر المنظومة</h2><small>جميع المبالغ بالدينار</small></div><div className="deskFooterFields deskSystemFields"><InvoiceField label="سعر بيع المنظومة · د.ع"><input aria-label="سعر بيع المنظومة" inputMode="decimal" placeholder="أدخل سعر البيع" value={moneyValue(salePrice)} onChange={e=>setSalePrice(rawMoney(e.target.value))}/></InvoiceField><InvoiceField label="ملاحظات الفاتورة"><textarea aria-label="ملاحظات الفاتورة" placeholder="اكتب ملاحظات الفاتورة هنا…" value={notes} onChange={e=>setNotes(e.target.value)}/></InvoiceField></div></section>
  <p className="systemExpenseNotice">تُحفظ المنظومة بدون مصاريف أولية. بعد التجهيز تعتمد الإدارة المصاريف النهائية وتغلق الملف.</p>
  <WarrantyEditor value={warranty} items={items} onChange={setWarranty}/>
  <InvoiceSummary entries={[["عدد الأصناف",items.length],["مجموع الكميات",fmt(items.reduce((sum,i)=>sum+(+i.qty||0),0))],["كلفة المواد",fmt(cost)+' د.ع'],["الكلفة الكلية",fmt(cost+(+expenses||0))+' د.ع'],["الربح الصافي",salePrice?fmt(profit)+' د.ع':'—']]} label="سعر بيع المنظومة" total={salePrice} empty={!salePrice}/>
  <InvoiceActions documentHtml={doc(true)} documentName={'فاتورة-منظومة-'+(party||'عميل')} saving={saving} onSave={saveSystem} saveLabel="حفظ المنظومة وإسناد التنصيب" onPreview={()=>openA4(doc(true))} onPdf={()=>saveA4(doc(true),'فاتورة-منظومة-'+(party||'عميل'))} onShare={()=>share(true)}><button onClick={()=>openA4(doc(false))}>معاينة النسخة المخزنية</button><button onClick={()=>saveA4(doc(false),'وصل-منظومة-مخزني')}>حفظ نسخة المخزن</button><button onClick={()=>share(false)}>مشاركة للمخزن</button></InvoiceActions>
 </InvoiceShell>{saved&&<section className="warrantySaved"><h2>تم حفظ منظومة #{saved.number}</h2>{saved.token&&<a href={warrantyUrl(saved.token)} target="_blank" rel="noopener noreferrer">فتح شهادة الضمان</a>}<ReportActions enabled html={saved.html} filename={'فاتورة-منظومة-'+saved.number}/><button onClick={()=>setSaved(null)}>إغلاق</button></section>}</>;
}

function StockReport({products,reconciliation}){const [cost,setCost]=useState(true),[query,setQuery]=useState(''),[brand,setBrand]=useState(''),[category,setCategory]=useState('');const available=products.filter(p=>(+p.qty||0)>0&&(!brand||p.brand===brand)&&(!category||p.category===category)&&[p.name,p.code,p.brand,p.category].join(' ').toLowerCase().includes(query.trim().toLowerCase()));const total=available.reduce((a,p)=>a+p.qty*p.cost,0);const makeText=()=>available.map(p=>p.name+' | '+p.qty+(cost?' | '+p.cost+' د.ع | '+fmt((+(p.bookQty??p.qty)||0)*(+p.cost||0))+' د.ع':'')).join('\n')+(cost?'\nالمجموع الكلي: '+fmt(total)+' د.ع':'');const stockHtml=()=>{const rows=available.map(p=>'<tr><td>'+p.name+'<br><small>'+(p.brand||'')+' '+(p.category||'')+'</small></td><td>'+(p.qty||'')+'</td>'+(cost?'<td>'+Number(p.cost||0).toLocaleString('en-US')+'</td><td>'+((+(p.bookQty??p.qty)||0)*(+p.cost||0)).toLocaleString('en-US')+'</td>':'')+'</tr>').join('');const body='<table><thead><tr><th>المادة</th><th>العدد</th>'+(cost?'<th>الكلفة د.ع</th><th>المجموع د.ع</th>':'')+'</tr></thead><tbody>'+rows+'</tbody></table>';return a4('كشف المخزون',body,cost?total.toLocaleString('en-US')+' د.ع':'',new Date().toLocaleDateString('ar-IQ'))}; const preview=()=>openA4(stockHtml());const share=async()=>{const text='مخزون عبدالرحمن سولار\n'+makeText();await shareA4('كشف-المخزون',text,stockHtml())};return <div><ReportActions enabled html={stockHtml()} filename="كشف-المخزون"/>{reconciliation}<div className="reportFilters"><input aria-label="بحث المخزون" placeholder="ابحث بالاسم أو الكود…" value={query} onChange={e=>setQuery(e.target.value)}/><select aria-label="البراند" value={brand} onChange={e=>setBrand(e.target.value)}><option value="">كل البراندات</option>{[...new Set(products.map(p=>p.brand).filter(Boolean))].map(b=><option key={b}>{b}</option>)}</select><select aria-label="الصنف" value={category} onChange={e=>setCategory(e.target.value)}><option value="">كل الأصناف</option>{[...new Set(products.map(p=>p.category).filter(Boolean))].map(c=><option key={c}>{c}</option>)}</select><small>{available.length} مادة متوفرة ضمن الفلتر</small></div><div className="reportOptions"><label><input type="checkbox" checked={cost} onChange={e=>setCost(e.target.checked)}/> مع الكلفة</label></div><div className={"stockTable"+(cost?"":" unpriced")}><div className="stockRow head"><b>المادة</b><b>العدد</b>{cost&&<><b>السعر</b><b>المجموع</b></>}</div>{available.map(p=><div className="stockRow" key={p.id}><span className="stockMaterial"><b>{p.name}</b><small>{p.brand||"بدون براند"} • {p.category||"بدون صنف"}</small></span><span>{p.qty}</span>{cost&&<><span>{fmt(p.cost)} د.ع</span><span>{fmt((+(p.bookQty??p.qty)||0)*(+p.cost||0))} د.ع</span></>}</div>)}</div>{cost&&<div className="grandTotal"><span>المجموع الكلي</span><b>{fmt(total)} د.ع</b></div>}</div>}

function PurchaseCurrencyEditor({row,products,suppliers,onUpdate,onCancel,canEditRate}){
 const [items,setItems]=useState([]),[search,setSearch]=useState('');
 return <CurrencyInvoice kind="purchase" initialInvoice={row} products={products} parties={suppliers} items={items} setItems={setItems} search={search} setSearch={setSearch} history={[row]} onUpdateInvoice={onUpdate} onCancel={onCancel} canEditRate={canEditRate} a4={a4} openA4={openA4} saveA4={saveA4} shareA4={shareA4}/>;
}
